const end = (why: ServeEnd): void => {
  if (ended) return;
  ended = true;
  for (const controller of inflight.values()) controller.abort();
  inflight.clear();
  input.off('data', onData);
  input.off('end', onEnd);
  input.off('error', onEnd);
  output.off('error', onEnd);
  finish(why);
